import sys

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N = int(input_data[idx]); idx+=1
    M = int(input_data[idx]); idx+=1
    grid = []
    for i in range(N):
        grid.append(input_data[idx]); idx+=1

    # Define constraints within a 9x9 region (0-indexed)
    # Black cells: top-left 3x3 and bottom-right 3x3
    black_cells = set()
    for r in range(3):
        for c in range(3):
            black_cells.add((r, c))
    for r in range(6, 9):
        for c in range(6, 9):
            black_cells.add((r, c))

    # White cells: adjacent to top-left 3x3 (outside it, within 9x9)
    # Adjacent means Chebyshev distance 1 from any cell in the 3x3
    white_cells = set()
    # Top-left 3x3 occupies rows 0-2, cols 0-2
    # Adjacent cells outside: row 3 cols 0-3, and col 3 rows 0-3
    for c in range(4):
        white_cells.add((3, c))
    for r in range(3):
        white_cells.add((r, 3))

    # Bottom-right 3x3 occupies rows 6-8, cols 6-8
    # Adjacent cells outside: row 5 cols 5-8, and col 5 rows 5-8
    for c in range(5, 9):
        white_cells.add((5, c))
    for r in range(6, 9):
        white_cells.add((r, 5))

    results = []
    for i in range(N - 8):
        for j in range(M - 8):
            valid = True
            for (dr, dc) in black_cells:
                if grid[i+dr][j+dc] != '#':
                    valid = False
                    break
            if not valid:
                continue
            for (dr, dc) in white_cells:
                if grid[i+dr][j+dc] != '.':
                    valid = False
                    break
            if valid:
                results.append((i+1, j+1))

    for (r, c) in results:
        print(r, c)

solve()

