import math
from typing import List
import sys
input = sys.stdin.readline

class Solution:
    def minNumberOfSeconds(self, mountainHeight: int, workerTimes: List[int]) -> int:
        def can_finish(T):
            total = 0
            for w in workerTimes:
                val = 2 * T / w
                x = int((-1 + math.sqrt(1 + 4 * val)) / 2)
                while (x + 1) * (x + 2) // 2 * w <= T:
                    x += 1
                while x > 0 and x * (x + 1) // 2 * w > T:
                    x -= 1
                total += x
                if total >= mountainHeight:
                    return True
            return total >= mountainHeight

        lo = 1
        hi = max(workerTimes) * mountainHeight * (mountainHeight + 1) // 2

        while lo < hi:
            mid = (lo + hi) // 2
            if can_finish(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

def main():
    data = sys.stdin.read().split()
    mountainHeight = int(data[0])
    workerTimes = list(map(int, data[1:]))
    sol = Solution()
    print(sol.minNumberOfSeconds(mountainHeight, workerTimes))

main()

