from typing import List

class Solution:
    def doesValidArrayExist(self, derived: List[int]) -> bool:
        # If we fix original[0] = 0, we can determine all other values
        # original[i+1] = original[i] XOR derived[i]
        # Then check if original[n-1] XOR original[0] == derived[n-1]

        # Try original[0] = 0
        original = [0] * len(derived)
        for i in range(len(derived) - 1):
            original[i + 1] = original[i] ^ derived[i]
        if original[-1] ^ original[0] == derived[-1]:
            return True

        # Try original[0] = 1
        original = [1] * len(derived)
        for i in range(len(derived) - 1):
            original[i + 1] = original[i] ^ derived[i]
        if original[-1] ^ original[0] == derived[-1]:
            return True

        return False

