from itertools import permutations

def count_inversions(perm):
    n = len(perm)
    count = 0
    for i in range(n):
        for j in range(i+1, n):
            if perm[i] > perm[j]:
                count += 1
    return count

def solve():
    import sys
    input_data = sys.stdin.read().split()
    idx = 0
    H = int(input_data[idx]); idx += 1
    W = int(input_data[idx]); idx += 1
    A = []
    for i in range(H):
        row = [int(input_data[idx+j]) for j in range(W)]
        idx += W
        A.append(row)
    B = []
    for i in range(H):
        row = [int(input_data[idx+j]) for j in range(W)]
        idx += W
        B.append(row)

    ans = float('inf')

    for rp in permutations(range(H)):
        inv_r = count_inversions(rp)
        if inv_r >= ans:
            continue
        for cp in permutations(range(W)):
            ok = True
            for i in range(H):
                for j in range(W):
                    if A[rp[i]][cp[j]] != B[i][j]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                inv_c = count_inversions(cp)
                total = inv_r + inv_c
                if total < ans:
                    ans = total

    print(-1 if ans == float('inf') else ans)

solve()

