from typing import List

class Solution:
    def maxScore(self, nums: List[int], x: int) -> int:
        NEG_INF = float('-inf')
        best_even = NEG_INF
        best_odd = NEG_INF

        # Initialize with nums[0]
        if nums[0] % 2 == 0:
            best_even = nums[0]
        else:
            best_odd = nums[0]

        for i in range(1, len(nums)):
            v = nums[i]
            if v % 2 == 0:
                candidate = v + max(best_even, best_odd - x if best_odd != NEG_INF else NEG_INF)
                best_even = max(best_even, candidate)
            else:
                candidate = v + max(best_odd, best_even - x if best_even != NEG_INF else NEG_INF)
                best_odd = max(best_odd, candidate)

