class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        n = len(s)
        best = 1
        left = 0
        consecutive_pairs = 0

        for right in range(1, n):
            if s[right] == s[right - 1]:
                consecutive_pairs += 1

            while consecutive_pairs > 1:
                if s[left] == s[left + 1]:
                    consecutive_pairs -= 1
                left += 1

            best = max(best, right - left + 1)

        return best

