import sys
from collections import defaultdict

def solve():
    MOD = 998244353
    input_data = sys.stdin.read().split()
    N = int(input_data[0])
    A = list(map(int, input_data[1:N+1]))

    ans = [0] * (N + 1)
    ans[1] = N % MOD

    if N == 1:
        print(ans[1])
        return

    # dp[j][i][length] = count of arith subseqs of given length ending at positions j then i
    dp = [[defaultdict(int) for _ in range(N)] for _ in range(N)]

    for i in range(N):
        for j in range(i):
            dp[j][i][2] = 1
            ans[2] = (ans[2] + 1) % MOD

    for length in range(3, N + 1):
        for i in range(N):
            for j in range(i):
                d = A[i] - A[j]
                for m in range(j):
                    if A[j] - A[m] == d:
                        val = dp[m][j].get(length - 1, 0)
                        if val:
                            dp[j][i][length] = (dp[j][i][length] + val) % MOD
                            ans[length] = (ans[length] + val) % MOD

    print(*[ans[k] for k in range(1, N+1)])

solve()

