def get_median(lst1, lst2, n):
    if n == 0:
        return None
    if n == 1:
        return (lst1[0] + lst2[0]) / 2.0

    def find_median(lst1, lst2, start1, start2, n):
        if n == 1:
            return (lst1[start1] + lst2[start2]) / 2.0
        if n == 2:
            return (max(lst1[start1], lst2[start2]) + min(lst1[start1+1], lst2[start2+1])) / 2.0

        mid = (n - 1) // 2
        m1 = lst1[start1 + mid]
        m2 = lst2[start2 + mid]

        if m1 == m2:
            return (m1 + m2) / 2.0
        elif m1 < m2:
            return find_median(lst1, lst2, start1 + mid, start2, n - mid)
        else:
            return find_median(lst1, lst2, start1, start2 + mid, n - mid)

    return find_median(lst1, lst2, 0, 0, n)

