def max_Product(arr):
    if len(arr) < 2:
        return None

    arr_sorted = sorted(arr)

    # The maximum product pair comes from either:
    # - The two largest positive numbers
    # - The two most negative numbers (largest absolute values)

    # Compare product of two largest vs two smallest
    n = len(arr_sorted)

    if arr_sorted[0] * arr_sorted[1] > arr_sorted[n-1] * arr_sorted[n-2]:
        a, b = arr_sorted[0], arr_sorted[1]
    else:
        a, b = arr_sorted[n-2], arr_sorted[n-1]

    return (min(a, b), max(a, b))

