from typing import List

def solve():
    input_data = sys.stdin.read().split()
    nums = list(map(int, input_data))

    n = len(nums)
    vals = [nums[i] - i for i in range(n)]

    sorted_vals = sorted(set(vals))
    rank = {v: i+1 for i, v in enumerate(sorted_vals)}
    m = len(sorted_vals)

    bit = [-float('inf')] * (m + 2)

    def update(pos, val):
        while pos <= m:
            if bit[pos] < val:
                bit[pos] = val
            pos += pos & (-pos)

    def query(pos):
        res = -float('inf')
        while pos > 0:
            if bit[pos] > res:
                res = bit[pos]
            pos -= pos & (-pos)
        return res

    ans = -float('inf')
    for i in range(n):
        r = rank[vals[i]]
        best_prev = query(r)
        if best_prev <= 0:
            dp_i = max(nums[i], nums[i] + best_prev) if best_prev > -float('inf') else nums[i]
        else:
            dp_i = nums[i] + best_prev
        ans = max(ans, dp_i)
        update(r, dp_i)

    print(ans)

solve()

