from typing import List
import sys

class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        n = len(circles)

        def touches_top_left(x, y, r):
            return x <= r or y + r >= yCorner

        def touches_bot_right(x, y, r):
            return x + r >= xCorner or y <= r

        def circles_intersect(c1, c2):
            x1, y1, r1 = c1
            x2, y2, r2 = c2
            dist2 = (x1-x2)**2 + (y1-y2)**2
            return dist2 <= (r1+r2)**2

        def covers_corner(x, y, r, cx, cy):
            return (x-cx)**2 + (y-cy)**2 < r**2

        for x, y, r in circles:
            if covers_corner(x, y, r, 0, 0) or covers_corner(x, y, r, xCorner, yCorner):
                return False

        top_left_circles = [i for i, (x,y,r) in enumerate(circles) if touches_top_left(x,y,r)]

        visited = [False] * n
        stack = []
        for i in top_left_circles:
            if not visited[i]:
                visited[i] = True
                stack.append(i)

        while stack:
            i = stack.pop()
            x1, y1, r1 = circles[i]
            if touches_bot_right(x1, y1, r1):
                return False
            for j in range(n):
                if not visited[j] and circles_intersect(circles[i], circles[j]):
                    visited[j] = True
                    stack.append(j)

        return True

def main():
    input_data = sys.stdin.read().split()
    xCorner = int(input_data[0])
    yCorner = int(input_data[1])
    n = int(input_data[2])
