    idx = 3
    for _ in range(n):
        circles.append([int(input_data[idx]), int(input_data[idx+1]), int(input_data[idx+2])])
        idx += 3
    sol = Solution()
    print(sol.canReachCorner(xCorner, yCorner, circles))

