class Solution:
    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        def count_up_to(N):
            if N <= 0:
                return 0
            N_str = str(N)
            s_len = len(s)
            n_len = len(N_str)
            result = 0
            for total_len in range(s_len, n_len + 1):
                prefix_len = total_len - s_len
                if prefix_len == 0:
                    num = int(s)
                    if num <= N:
                        result += 1
                else:
                    if total_len < n_len:
                        result += limit * ((limit + 1) ** (prefix_len - 1))
                    else:
                        tight_prefix = N_str[:prefix_len]
                        suffix_ok = s <= N_str[prefix_len:]
                        count = 0
                        for i in range(prefix_len):
                            max_d = int(tight_prefix[i])
                            lo = 1 if i == 0 else 0
                            free_max = min(max_d - 1, limit)
                            if free_max >= lo:
                                count += (free_max - lo + 1) * ((limit + 1) ** (prefix_len - i - 1))
                            if max_d > limit:
                                break
                        else:
                            if suffix_ok:
                                count += 1
                        result += count
            return result

        return count_up_to(finish) - count_up_to(start - 1)

