class Solution:
    def minChanges(self, n: int, k: int) -> int:
        # Check if k has any bit set that n doesn't have
        # We can only turn 1s to 0s, so if k has a 1 where n has a 0, impossible
        if (n & k) != k:
            return -1
        # Count the number of bits that are 1 in n but 0 in k
        diff = n ^ k  # bits that differ
        return bin(diff).count('1')

