def minPath(grid, k):
    n = len(grid)

    # Find position of value 1
    pos = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                pos = (i, j)
                break
        if pos is not None:
            break

    # Find minimum neighbor value
    r, c = pos
    min_neighbor = float('inf')
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n:
            min_neighbor = min(min_neighbor, grid[nr][nc])

    # Build path: alternate between 1 and min_neighbor
    path = []
    for i in range(k):
        if i % 2 == 0:
            path.append(1)
        else:
            path.append(min_neighbor)

