from itertools import permutations
import sys

def solve():
    grid = []
    for line in sys.stdin:
        grid.extend(map(int, line.split()))

    lines = [
        [0,1,2], [3,4,5], [6,7,8],
        [0,3,6], [1,4,7], [2,5,8],
        [0,4,8], [6,4,2]
    ]

    total = 0
    good = 0

    for perm in permutations(range(9)):
        total += 1
        # Build position lookup: pos[cell] = step at which cell is seen
        pos = [0] * 9
        for step, cell in enumerate(perm):
            pos[cell] = step

        disappointed = False
        for line in lines:
            a, b, c = line
            pa, pb, pc = pos[a], pos[b], pos[c]
            # Sort by position
            if pa <= pb <= pc:
                first, second, third = a, b, c
            elif pa <= pc <= pb:
                first, second, third = a, c, b
            elif pb <= pa <= pc:
                first, second, third = b, a, c
            elif pb <= pc <= pa:
                first, second, third = b, c, a
            elif pc <= pa <= pb:
                first, second, third = c, a, b
            else:
                first, second, third = c, b, a

            if grid[first] == grid[second] and grid[second] != grid[third]:
                disappointed = True
                break

        if not disappointed:
            good += 1

    print(good / total)

solve()

