from typing import List

class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        max_len = -1

        for i in range(n - 1):
            if nums[i + 1] - nums[i] == 1:
                # Start of a potential alternating subarray
                length = 2
                max_len = max(max_len, length)
                j = i + 2
                while j < n:
                    expected_diff = (-1) ** (j - i)
                    if nums[j] - nums[j - 1] == expected_diff:
                        length += 1
                        max_len = max(max_len, length)
                        j += 1
                    else:
                        break

        return max_len

