import sys
from collections import defaultdict
from typing import List

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1

        freq = defaultdict(int)
        for x in nums:
            freq[x] += 1

        ops = 0

        for bit in range(31):
            val = 1 << bit
            if target & val:
                if freq[val] > 0:
                    freq[val] -= 1
                else:
                    next_bit = bit + 1
                    while next_bit <= 31 and freq[1 << next_bit] == 0:
                        next_bit += 1
                    for b in range(next_bit, bit, -1):
                        freq[1 << b] -= 1
                        freq[1 << (b - 1)] += 2
                        ops += 1
                    freq[val] -= 1

            if freq[val] > 1:
                freq[val * 2] += freq[val] // 2
                freq[val] = freq[val] % 2

        return ops

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx += 1
    nums = [int(input_data[idx + i]) for i in range(n)]; idx += n
    target = int(input_data[idx])
    sol = Solution()
    print(sol.minOperations(nums, target))

