import sys
from typing import List

class Solution:
    def countOfPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)

        bit = [0] * (n + 1)

        def update(i, delta):
            i += 1
            while i <= n:
                bit[i] += delta
                i += i & (-i)

        def query(i):
            i += 1
            s = 0
            while i > 0:
                s += bit[i]
                i -= i & (-i)
            return s

        def range_query(l, r):
            if l > r:
                return 0
            res = query(r)
            if l > 0:
                res -= query(l - 1)
            return res

        def is_peak(i):
            if i <= 0 or i >= n - 1:
                return False
            return nums[i] > nums[i-1] and nums[i] > nums[i+1]

        peak_status = [0] * n

        for i in range(1, n - 1):
            if is_peak(i):
                peak_status[i] = 1
                update(i, 1)

        def update_peak(i):
            if i <= 0 or i >= n - 1:
                return
            new_val = 1 if is_peak(i) else 0
            if new_val != peak_status[i]:
                update(i, new_val - peak_status[i])
                peak_status[i] = new_val

        result = []

        for q in queries:
            if q[0] == 1:
                l, r = q[1], q[2]
                if r - l < 2:
                    result.append(0)
                else:
                    result.append(range_query(l + 1, r - 1))
            else:
                idx, val = q[1], q[2]
                nums[idx] = val
                update_peak(idx - 1)
                update_peak(idx)
                update_peak(idx + 1)

        return result

if __name__ == "__main__":
