        t = int(data[idx]); idx += 1
        a = int(data[idx]); idx += 1
        b = int(data[idx]); idx += 1
        queries.append([t, a, b])

    sol = Solution()
    ans = sol.countOfPeaks(nums, queries)
    print('\n'.join(map(str, ans)))

