    W = int(input_data[idx]); idx+=1
    grid = []
    for i in range(H):
        grid.append(input_data[idx]); idx+=1

    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    def is_free(i, j):
        if grid[i][j] == '#': return False
        for di, dj in dirs:
            ni, nj = i+di, j+dj
            if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                return False
        return True

    free = [[is_free(i,j) for j in range(W)] for i in range(H)]

    visited = [[False]*W for _ in range(H)]
    max_dof = 1  # at least 1 since there's at least one cell without magnet

    for si in range(H):
        for sj in range(W):
            if free[si][sj] and not visited[si][sj]:
                queue = deque([(si, sj)])
                visited[si][sj] = True
                component_size = 0
                border_stuck = set()
                while queue:
                    i, j = queue.popleft()
                    component_size += 1
                    for di, dj in dirs:
                        ni, nj = i+di, j+dj
                        if 0 <= ni < H and 0 <= nj < W:
