def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # inc[i] = max sum of increasing subsequence ending at index i
    inc = arr[:]
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # dec[i] = max sum of decreasing subsequence starting at index i
    dec = arr[:]
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # max bitonic sum: inc[i] + dec[i] - arr[i] (to avoid double counting)
    result = 0
    for i in range(n):
        result = max(result, inc[i] + dec[i] - arr[i])

    return result

