def eulerian_num(n, m):
    # Base cases
    if m >= n or m < 0:
        return 0
    if n == 0:
        return 1

    # Build table using dynamic programming
    # dp[i][j] = Eulerian number A(i, j)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(0, i):
            dp[i][j] = (j + 1) * dp[i-1][j] + (i - j) * dp[i-1][j-1]

    return dp[n][m]

import sys
from typing import List
from collections import defaultdict

class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        value_to_rows = defaultdict(set)
        for r, row in enumerate(grid):
            for val in row:
                value_to_rows[val].add(r)

        dp = {0: 0}

        for val, rows in value_to_rows.items():
            rows = list(rows)
            new_dp = dict(dp)
            for mask, score in dp.items():
                for r in rows:
                    if not (mask & (1 << r)):
                        new_mask = mask | (1 << r)
                        if new_mask not in new_dp or new_dp[new_mask] < score + val:
                            new_dp[new_mask] = score + val
            dp = new_dp

        return max(dp.values())

