from itertools import permutations

def solve():
    N = int(input())
    R = input().strip()
    C = input().strip()

    grid = [['.']*N for _ in range(N)]
    col_count = [[0,0,0] for _ in range(N)]  # A,B,C counts per column

    def backtrack(row):
        if row == N:
            # Check column constraints: each column must have exactly one A,B,C
            for j in range(N):
                if col_count[j][0] != 1 or col_count[j][1] != 1 or col_count[j][2] != 1:
                    return False
                # Check topmost character
                for r in range(N):
                    if grid[r][j] != '.':
                        if grid[r][j] != C[j]:
                            return False
                        break
            return True

        # Try all permutations of 3 distinct columns for A, B, C
        for cols in permutations(range(N), 3):
            ca, cb, cc = cols  # column for A, B, C
            # Check leftmost constraint
            leftmost_col = min(ca, cb, cc)
            if leftmost_col == ca:
                ch = 'A'
            elif leftmost_col == cb:
                ch = 'B'
            else:
                ch = 'C'
            if ch != R[row]:
                continue
            # Check column capacity
            if col_count[ca][0] >= 1 or col_count[cb][1] >= 1 or col_count[cc][2] >= 1:
                continue
            # Place
            grid[row][ca] = 'A'; grid[row][cb] = 'B'; grid[row][cc] = 'C'
            col_count[ca][0] += 1; col_count[cb][1] += 1; col_count[cc][2] += 1

            if backtrack(row + 1):
                return True

            grid[row][ca] = '.'; grid[row][cb] = '.'; grid[row][cc] = '.'
            col_count[ca][0] -= 1; col_count[cb][1] -= 1; col_count[cc][2] -= 1

        return False

    if backtrack(0):
        print("Yes")
        for row in grid:
            print(''.join(row))
    else:
        print("No")

