class Solution:
    def maximumValueSum(self, board: List[List[int]]) -> int:
        m = len(board)
        n = len(board[0])

        # For each row, precompute top 3 (col, value) entries sorted by value desc
        top3 = []
        for i in range(m):
            row = board[i]
            indexed = sorted(range(n), key=lambda c: -row[c])
            top3.append([(c, row[c]) for c in indexed[:3]])

        best = -float('inf')

        for r1, r2, r3 in combinations(range(m), 3):
            for (c1, v1) in top3[r1]:
                for (c2, v2) in top3[r2]:
                    if c2 == c1:
                        continue
                    for (c3, v3) in top3[r3]:
                        if c3 == c1 or c3 == c2:
                            continue
                        s = v1 + v2 + v3
                        if s > best:
