import math

class Solution:
    def nonSpecialCount(self, l: int, r: int) -> int:
        # Special numbers are squares of primes
        # Find all primes up to sqrt(r)
        limit = int(math.isqrt(r))

        # Sieve of Eratosthenes up to limit
        sieve = [True] * (limit + 1)
        sieve[0] = False
        if limit >= 1:
            sieve[1] = False
        for i in range(2, int(math.isqrt(limit)) + 1):
            if sieve[i]:
                for j in range(i*i, limit + 1, i):
                    sieve[j] = False

        # Count primes p where l <= p^2 <= r
        special_count = 0
        for p in range(2, limit + 1):
            if sieve[p]:
                sq = p * p
                if l <= sq <= r:
                    special_count += 1

        total = r - l + 1
        return total - special_count

