from typing import List
import sys

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # dp[i][j] = max length of good subsequence ending at i with j transitions
        dp = [[0] * (k + 1) for _ in range(n)]

        for i in range(n):
            dp[i][0] = 1

        ans = 1

        for i in range(1, n):
            for prev in range(i):
                if nums[i] == nums[prev]:
                    for j in range(k + 1):
                        if dp[prev][j] > 0:
                            if dp[prev][j] + 1 > dp[i][j]:
                                dp[i][j] = dp[prev][j] + 1
                else:
                    for j in range(1, k + 1):
                        if dp[prev][j-1] > 0:
                            if dp[prev][j-1] + 1 > dp[i][j]:
                                dp[i][j] = dp[prev][j-1] + 1

            for j in range(k + 1):
                if dp[i][j] > ans:
                    ans = dp[i][j]

        return ans

