import sys
from collections import deque
from typing import List

class Solution:
    def minimumDiameterAfterMerge(self, edges1: List[List[int]], edges2: List[List[int]]) -> int:
        def build_adj(edges, n):
            adj = [[] for _ in range(n)]
            for u, v in edges:
                adj[u].append(v)
                adj[v].append(u)
            return adj

        def bfs_farthest(adj, start, n):
            dist = [-1] * n
            dist[start] = 0
            q = deque([start])
            farthest = start
            max_dist = 0
            while q:
                node = q.popleft()
                for nb in adj[node]:
                    if dist[nb] == -1:
                        dist[nb] = dist[node] + 1
                        if dist[nb] > max_dist:
                            max_dist = dist[nb]
                            farthest = nb
                        q.append(nb)
            return farthest, max_dist

        def get_diameter(edges, n):
            if n == 1:
                return 0
            adj = build_adj(edges, n)
            u, _ = bfs_farthest(adj, 0, n)
            v, diam = bfs_farthest(adj, u, n)
            return diam

        n = len(edges1) + 1
        m = len(edges2) + 1

        d1 = get_diameter(edges1, n)
        d2 = get_diameter(edges2, m)

        combined = (d1 + 1) // 2 + (d2 + 1) // 2 + 1

        return max(d1, d2, combined)

