import sys

def solve():
    input_data = sys.stdin.read().split()
    N = int(input_data[0])
    A = list(map(int, input_data[1:N+1]))

    # Precompute smallest prime factor
    MAX_VAL = 10**5 + 1
    spf = list(range(MAX_VAL))
    for i in range(2, MAX_VAL):
        if spf[i] == i:  # i is prime
            for j in range(i*i, MAX_VAL, i):
                if spf[j] == j:
                    spf[j] = i

    def omega(n):
        count = 0
        while n > 1:
            p = spf[n]
            while n % p == 0:
                n //= p
                count += 1
        return count

    xor_sum = 0
    for a in A:
        xor_sum ^= omega(a)

    print("Anna" if xor_sum != 0 else "Bruno")

solve()

from typing import List
import sys

class Solution:
    def maxValue(self, nums: List[int], k: int) -> int:
        n = len(nums)

        left_sets = [set() for _ in range(n + 1)]
        dp = [set() for _ in range(k + 1)]
        dp[0].add(0)

        for i in range(1, n + 1):
            val = nums[i - 1]
            new_dp = [set() for _ in range(k + 1)]
            for j in range(k + 1):
                new_dp[j] |= dp[j]
                if j > 0:
                    for v in dp[j - 1]:
                        new_dp[j].add(v | val)
            dp = new_dp
            left_sets[i] = set(dp[k])

        right_sets = [set() for _ in range(n + 1)]
        dp2 = [set() for _ in range(k + 1)]
        dp2[0].add(0)

        for i in range(n - 1, -1, -1):
            val = nums[i]
            new_dp = [set() for _ in range(k + 1)]
            for j in range(k + 1):
                new_dp[j] |= dp2[j]
                if j > 0:
                    for v in dp2[j - 1]:
                        new_dp[j].add(v | val)
            dp2 = new_dp
            right_sets[i] = set(dp2[k])

        ans = 0
        for i in range(k, n - k + 1):
            for a in left_sets[i]:
                for b in right_sets[i]:
                    ans = max(ans, a ^ b)

        return ans

