def solve():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    polys = []
    for i in range(3):
        grid = lines[i*4:(i+1)*4]
        cells = []
        for r in range(4):
            for c in range(4):
                if grid[r][c] == '#':
                    cells.append((r, c))
        polys.append(cells)

    def normalize(cells):
        min_r = min(r for r, c in cells)
        min_c = min(c for r, c in cells)
        return tuple(sorted((r - min_r, c - min_c) for r, c in cells))

    def rotate90(cells):
        return [(c, -r) for r, c in cells]

    def get_rotations(cells):
        rotations = set()
        current = list(cells)
        for _ in range(4):
            rotations.add(normalize(current))
            current = rotate90(current)
        return list(rotations)

    def get_placements(norm_cells):
        placements = []
        for dr in range(4):
            for dc in range(4):
                placed = tuple((r + dr, c + dc) for r, c in norm_cells)
                if all(0 <= r < 4 and 0 <= c < 4 for r, c in placed):
                    placements.append(frozenset(placed))
        return placements

    all_placements = []
    for poly in polys:
        rots = get_rotations(poly)
        pset = set()
        for rot in rots:
            for pl in get_placements(rot):
                pset.add(pl)
