import sys
from collections import defaultdict

class Solution:
    def maxPartitionsAfterOperations(self, s: str, k: int) -> int:
        n = len(s)

        def count_from(start, string):
            cnt = defaultdict(int)
            partitions = 0
            for ch in string[start:]:
                if ch not in cnt and len(cnt) == k:
                    partitions += 1
                    cnt = defaultdict(int)
                cnt[ch] += 1
            if cnt:
                partitions += 1
            return partitions

        # Precompute suffix partition counts
        suffix = [0] * (n + 1)
        cnt = defaultdict(int)
        part_starts = []
        i = 0
        while i < n:
            if s[i] not in cnt and len(cnt) == k:
                part_starts.append(i)
                cnt = defaultdict(int)
            cnt[s[i]] += 1
            i += 1
        part_starts.append(n)

        # suffix[i] = number of partitions of s[i:]
        # Compute via simulation for each i (cache)
        next_part_start = [n] * n
        cnt = {}
        j = 0
        start = 0
        for j in range(n):
            if s[j] not in cnt and len(cnt) == k:
                for jj in range(start, j):
                    next_part_start[jj] = j
                start = j
                cnt = {}
            cnt[s[j]] = cnt.get(s[j], 0) + 1

        from functools import lru_cache
        @lru_cache(maxsize=None)
        def right_parts(i):
            if i >= n:
                return 0
            cnt2 = {}
            j = i
            while j < n:
                if s[j] not in cnt2 and len(cnt2) == k:
                    return 1 + right_parts(j)
                cnt2[s[j]] = cnt2.get(s[j], 0) + 1
                j += 1
            return 1

        base = right_parts(0)

        best = base

        for i in range(n):
            # Try changing s[i] to a new character
            # Simulate prefix up to i
            cnt2 = {}
            partitions = 0
            cur_start = 0
            forced_break = False
            for j in range(i):
                if s[j] not in cnt2 and len(cnt2) == k:
                    partitions += 1
                    cnt2 = {}
                    cur_start = j
                cnt2[s[j]] = cnt2.get(s[j], 0) + 1

            # Now at position i, try changing to a char not in cnt2
            # Best: add a new char (not in cnt2) - if len(cnt2) == k, this forces break
            # If len(cnt2) < k, adding new char just extends window
            # If len(cnt2) == k, adding new char forces break at i, then s[i] starts new partition

            if len(cnt2) < k:
                # Adding new char: window has len(cnt2)+1 distinct, still <= k if len(cnt2)+1<=k
                # The new char at i doesn't force a break before i
                # Window continues with new char; then from i+1 onwards
                # We need to simulate i+1 onwards with cnt2 updated
                new_cnt = dict(cnt2)
                # add a brand new character
                new_cnt['_new_'] = 1  # placeholder for new char
                # simulate from i+1
                for j in range(i+1, n):
                    if s[j] not in new_cnt and len(new_cnt) == k:
                        partitions += 1
                        total = partitions + right_parts(j)
                        best = max(best, total)
                        new_cnt = {}
                    new_cnt[s[j]] = new_cnt.get(s[j], 0) + 1
                # also consider: new char same as existing - no benefit
                # end of string
                best = max(best, partitions + 1)
            else:
                # len(cnt2) == k, adding new char forces break at i
                partitions += 1  # partition from cur_start to i-1
                # now s[i] is changed to new char, starts new partition
                new_cnt = {'_new_': 1}
                for j in range(i+1, n):
                    if s[j] not in new_cnt and len(new_cnt) == k:
                        partitions += 1
                        total = partitions + right_parts(j)
                        best = max(best, total)
                        new_cnt = {}
                    new_cnt[s[j]] = new_cnt.get(s[j], 0) + 1
                best = max(best, partitions + 1)

        return best

def main():
    import sys
    input_data = sys.stdin.read().split()
    s = input_data[0]
    k = int(input_data[1])
    sol = Solution()
    print(sol.maxPartitionsAfterOperations(s, k))

