import math

def count_binary_seq(n):
    # Count binary sequences of length 2n where sum of first n bits equals sum of last n bits
    # For each possible sum k (0 to n), count sequences where first n bits sum to k
    # and last n bits sum to k, then multiply and add all possibilities
    # C(n,k) * C(n,k) for k from 0 to n
    result = 0
    for k in range(n + 1):
        result += math.comb(n, k) ** 2
    return float(result)

