from collections import deque

class Solution:
    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        m = len(grid)
        n = len(grid[0])

        # BFS with state (row, col, remaining_health)
        # visited[i][j] = max health seen at (i,j)
        visited = [[-1] * n for _ in range(m)]

        start_health = health - grid[0][0]
        if start_health <= 0:
            return False

        queue = deque()
        queue.append((0, 0, start_health))
        visited[0][0] = start_health

        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        while queue:
            r, c, h = queue.popleft()

            if r == m - 1 and c == n - 1:
                return True

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    nh = h - grid[nr][nc]
                    if nh > 0 and nh > visited[nr][nc]:
                        visited[nr][nc] = nh
                        queue.append((nr, nc, nh))

        return False
