import sys
from collections import defaultdict
from typing import List

class Solution:
    def timeTaken(self, edges: List[List[int]]) -> List[int]:
        n = len(edges) + 1
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        def w(v):
            return 1 if v % 2 == 1 else 2

        parent = [-1] * n
        order = []
        visited = [False] * n
        stack = [0]
        visited[0] = True
        while stack:
            node = stack.pop()
            order.append(node)
            for nb in adj[node]:
                if not visited[nb]:
                    visited[nb] = True
                    parent[nb] = node
                    stack.append(nb)

        down = [0] * n
        for node in reversed(order):
            best = 0
            for nb in adj[node]:
                if nb != parent[node]:
                    best = max(best, w(nb) + down[nb])
            down[node] = best

        up = [0] * n
        for node in order:
            children_vals = []
            for nb in adj[node]:
                if nb != parent[node]:
                    children_vals.append((w(nb) + down[nb], nb))
            children_vals.sort(reverse=True)

            for nb in adj[node]:
                if nb != parent[node]:
                    if len(children_vals) >= 1 and children_vals[0][1] != nb:
                        best_excl = children_vals[0][0]
                    elif len(children_vals) >= 2:
                        best_excl = children_vals[1][0]
                    else:
                        best_excl = 0
                    up[nb] = w(nb) + max(up[node], best_excl)

        return [max(down[i], up[i]) for i in range(n)]

def main():
    data = sys.stdin.read().split()
    idx = 0
    n_edges = int(data[idx]); idx += 1
    edges = []
    for _ in range(n_edges):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        edges.append([u, v])
    sol = Solution()
    print(sol.timeTaken(edges))

if __name__ == '__main__':
    main()

def max_product(arr):
    n = len(arr)
    if n == 0:
        return 0

    # dp[i] stores the maximum product of increasing subsequence ending at index i
    dp = [arr[i] for i in range(n)]

    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i] = max(dp[i], dp[j] * arr[i])

    return max(dp)

